**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <string>
using namespace std;

struct Osoba {
    string imie;
    int w[3];
    int suma() { return w[0] + w[1] + w[2]; }
};

int main() {
    ifstream plik("wyniki.txt");
    int N;
    plik >> N;
    vector<Osoba> tab(N);
    for (int i = 0; i < N; i++)
        plik >> tab[i].imie >> tab[i].w[0] >> tab[i].w[1] >> tab[i].w[2];

    // a) Max suma
    int idxMaxS = 0;
    for (int i = 1; i < N; i++)
        if (tab[i].suma() > tab[idxMaxS].suma()) idxMaxS = i;

    // b) Min suma
    int idxMinS = 0;
    for (int i = 1; i < N; i++)
        if (tab[i].suma() < tab[idxMinS].suma()) idxMinS = i;

    // c) Max pojedynczy wynik
    int maxW = tab[0].w[0], maxOsoba = 0, maxNr = 0;
    for (int i = 0; i < N; i++)
        for (int j = 0; j < 3; j++)
            if (tab[i].w[j] > maxW) {
                maxW = tab[i].w[j];
                maxOsoba = i;
                maxNr = j;
            }

    cout << "a) Max suma: " << tab[idxMaxS].imie << " (" << tab[idxMaxS].suma() << ")" << endl;
    cout << "b) Min suma: " << tab[idxMinS].imie << " (" << tab[idxMinS].suma() << ")" << endl;
    cout << "c) Max pojedynczy wynik: " << tab[maxOsoba].imie
         << " (" << maxW << ", wynik " << maxNr + 1 << ")" << endl;
    return 0;
}
```

**Wyjasnienie**: Struct z tablica 3 wynikow i metoda suma(). Trzy przeszukania: (a,b) po sumach, (c) podwojna petla po osobach i wynikach.

